/**
 * Publish the Look catalog into the skill as markdown (not TSX).
 * Source: packages/ui-examples/src/looks/catalog.json
 */
import fs from "node:fs"
import path from "node:path"

export function writeSkillLooks({ repoRoot, skillRef }) {
  const src = path.join(repoRoot, "packages/ui-examples/src/looks/catalog.json")
  const catalog = JSON.parse(fs.readFileSync(src, "utf8"))
  const outDir = path.join(skillRef, "looks")
  fs.rmSync(outDir, { recursive: true, force: true })
  fs.mkdirSync(outDir, { recursive: true })

  const index = [
    "<!-- generated by scripts/gen/skill — do not edit -->",
    "",
    "# Looks",
    "",
    "Recommended visual recipes (colour intent + layout grammar + surface). **Not apps.**",
    "Pick a facade first. Open a Look only when the user names a style.",
    "No kit API — copy the class literals. Light and dark are a pair (live fixture + theme.css, not image previews).",
    "",
    "| id | name | when | default facade |",
    "|---|---|---|---|",
  ]
  for (const look of catalog.looks) {
    const name = `${look.name.en} (\`${look.name.zh}\`)`
    const facades = look.defaultFor.length ? look.defaultFor.map((id) => `\`${id}\``).join(", ") : "—"
    index.push(`| [\`${look.id}\`](./${look.id}.md) | ${name} | ${look.when} | ${facades} |`)
  }
  index.push("")
  fs.writeFileSync(path.join(outDir, "index.md"), index.join("\n"))

  for (const look of catalog.looks) {
    const classes = Object.entries(look.classes)
      .map(([k, v]) => `- \`${k}\`: \`${v}\``)
      .join("\n")
    // A look whose identity depends on hue ships its own palette (same contract as the
    // host's themes/theme-*.css). Neutral looks deliberately omit it and follow the host.
    const themeCss = look.theme
      ? fs.readFileSync(path.join(repoRoot, "packages/ui-examples/src/looks", look.theme), "utf8").trimEnd()
      : null
    const body = [
      "<!-- generated by scripts/gen/skill — do not edit -->",
      "",
      `# ${look.name.en}`,
      "",
      `Also known as \`${look.name.zh}\` (sample product copy).`,
      "",
      `id: \`${look.id}\` · grammar: \`${look.grammar}\``,
      "",
      `**When:** ${look.when}`,
      "",
      `**Not:** ${look.whenNot}`,
      "",
      look.notes ? `**How to copy it:** ${look.notes}` : null,
      "",
      look.style
        ? [
            "## Style (inline — Tailwind drops multi-layer shadows)",
            "",
            "```tsx",
            `const GLASS = ${JSON.stringify(look.style, null, 2)} as const;`,
            "```",
            "",
          ]
        : [],
      "## Classes (copy literals)",
      "",
      classes,
      "",
      themeCss
        ? [
            "## Palette (optional `theme.css` in the app dir)",
            "",
            "This look's identity depends on hue, so it ships a palette. Writing it to `theme.css`",
            "makes the app use it by default (ThemePop lists it as the row tagged **`本应用`**); the user can still",
            "pick a host palette. Omit the file to follow the host palette instead.",
            "",
            "```css",
            themeCss,
            "```",
            "",
          ].join("\n")
        : "This look follows the host palette on purpose — no `theme.css`.",
      "",
      "Tokens only — no hex in `ui.tsx`. Light and dark must both read. Optional `data-look` on a root is a recipe, not a platform attribute.",
      "",
    ].filter((line) => line !== null).flat()
    fs.writeFileSync(path.join(outDir, `${look.id}.md`), body.join("\n"))
  }
}
